import { useMemo, useState } from 'react';

/**
 * Searchable stop picker: a text filter above the native select. Deliberately
 * not a combobox — the native select keeps keyboard/mobile behavior and the
 * dark color-scheme for free; the filter just shrinks the option list.
 * Empty filter shows all stops (current behavior). No matches -> honest hint.
 */
/**
 * Common GTFS street-suffix abbreviations. Matching "road" against "Rd" is
 * NOT prefix matching (neither is a prefix of the other) — it's abbreviation
 * expansion, so both sides are checked against this map.
 */
const SUFFIX_EXPANSIONS: Record<string, string[]> = {
  rd: ['road'],
  road: ['rd'],
  dr: ['drive'],
  drive: ['dr'],
  st: ['street'],
  street: ['st'],
  ave: ['avenue'],
  avenue: ['ave'],
  blvd: ['boulevard'],
  boulevard: ['blvd'],
  ln: ['lane'],
  lane: ['ln'],
  hts: ['heights'],
  heights: ['hts'],
  ctr: ['centre', 'center'],
  centre: ['ctr', 'center'],
  center: ['ctr', 'centre'],
};

export default function StopSearch({
  stops,
  value,
  onChange,
}: {
  stops: { stop_id: string; label: string }[];
  value: string;
  onChange: (stopId: string) => void;
}) {
  const [query, setQuery] = useState('');

  const filtered = useMemo(() => {
    // Match on ALL whitespace-separated terms ("city centre" finds City
    // Centre Terminal). Every term must match somewhere in the label; order
    // doesn't matter.
    //
    // Three ways a term can match a label word:
    //  1. exact word equality;
    //  2. prefix of one another, but ONLY when the shorter word has >= 3
    //     chars — "credit" finds "Creditview", yet "drive" must NOT match
    //     the platform letter "D" in "... Platform D" (user pass-2 finding);
    //  3. known suffix abbreviation via the expansion map ("road" finds
    //     "Rd" — abbreviation, not prefix, so the map is required).
    const terms = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
    if (terms.length === 0) return stops;
    return stops.filter((s) => {
      const label = s.label.toLowerCase();
      const words = label.split(/\s+/);
      return terms.every((t) =>
        words.some((w) => {
          if (w === t) return true;
          if (
            Math.min(w.length, t.length) >= 3 &&
            (w.startsWith(t) || t.startsWith(w))
          ) {
            return true;
          }
          const wExp = SUFFIX_EXPANSIONS[w];
          const tExp = SUFFIX_EXPANSIONS[t];
          return (
            (wExp !== undefined && wExp.includes(t)) ||
            (tExp !== undefined && tExp.includes(w))
          );
        }),
      );
    });
  }, [stops, query]);

  // If a selected stop is filtered out, keep it visible so the select never
  // shows a value with no matching option.
  const options = useMemo(() => {
    if (!value || filtered.some((s) => s.stop_id === value)) return filtered;
    const selected = stops.find((s) => s.stop_id === value);
    return selected ? [selected, ...filtered] : filtered;
  }, [filtered, stops, value]);

  return (
    <div>
      <input
        type="search"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Type to filter stops…"
        aria-label="Filter transfer stops"
        className="mb-1.5 w-full rounded border border-border bg-card px-2 py-1.5 text-sm text-text-primary placeholder:text-text-muted"
      />
      <select
        className="w-full rounded border border-border bg-card p-2 text-sm text-text-primary"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        aria-label="Transfer stop"
      >
        <option value="">— choose a stop —</option>
        {options.map((s) => (
          <option key={s.stop_id} value={s.stop_id}>
            {s.label}
          </option>
        ))}
      </select>
      {query.trim() && options.length === 0 && (
        <p className="mt-1 text-xs text-text-muted">
          No stops match “{query.trim()}”.
        </p>
      )}
    </div>
  );
}
